 * @param {number} n - A non-negative integer.
 * @returns {number} The sum of squares from 1 to n.
 */
function sumOfSquares(n) {
  let sum = 0;

  for (let i = 1; i <= n; i++) {
    sum += i * i;
  }

  return sum;
}

// Example usage:
